from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def b(vi,en):return {'vi':vi,'en':en}
def step(title,body,q,options,answer,reveal):return dict(title=b(*title),body=b(*body),question=b(*q),options=[b(*o) for o in options],answer=answer,reveal=b(*reveal))
stories=[{'id':'returned_letters','title':b('Ngoại truyện · Những lá thư trả lại','Side story · Returned letters'),'unlock':1,'steps':[
step(('Dấu bưu điện','The postmark'),('Bà Tư tìm được ba phong bì. Lá A gửi ngày 21/8, trả lại 25/8 vì không còn người nhận. Lá B gửi 2/9 đến địa chỉ mới, nhận ngày 5/9. Lá C là bản nháp chưa dán tem. Sổ chuyển địa chỉ ghi gia đình Lan đăng ký nơi mới ngày 28/8.','Mrs Tư finds three envelopes. A was sent on 21 August and returned on 25 August: recipient gone. B was sent on 2 September to the new address and received on 5 September. C is an unstamped draft. The family registered the new address on 28 August.'),('Lá nào chứng minh một thư đã đến nơi ở mới?','Which proves a letter reached the new home?'),[('Lá A','Letter A'),('Lá B','Letter B'),('Lá C','Letter C')],1,('Một lá thư bị trả lại không chứng minh cả gia đình từ chối liên lạc.','A returned letter does not prove the family refused all contact.')),
step(('Số tiền trên phiếu','The remittance slip'),('Phiếu tháng chín ghi gửi 300.000 đồng, phí 5.000 đồng; tổng người gửi trả 305.000. Sổ của Lan ghi nhận 300.000 và mua máy may cũ cùng tiền tiết kiệm. Một ghi chú khác gọi tổng 305.000 là tiền Lan nhận.','September’s slip lists 300,000 đồng sent, a 5,000 fee, and 305,000 paid by the sender. Lan records receiving 300,000, which she combined with savings to buy a used sewing machine. Another note calls the entire 305,000 her receipt.'),('Cần sửa con số nào trong bản ghi về tiền Lan nhận?','What should the receipt record say?'),[('305.000','305,000'),('5.000','5,000'),('300.000','300,000')],2,('Phí dịch vụ không phải tiền bồi thường. Sự chính xác nhỏ ngăn một lời kể hào phóng quá mức.','A service fee is not compensation. A small correction prevents an exaggerated account of generosity.')),
step(('Quyền được từ chối','The right to refuse'),('Lan viết: “Tôi nhận khoản tháng chín vì cần máy may. Tháng mười tôi gửi lại. Đừng viết rằng nhận tiền nghĩa là tôi đã đồng ý với việc mất nhà.” Bản nháp của An lại có câu: “Hai gia đình đã hòa giải từ năm ấy.”','Lan writes: “I accepted September’s money because I needed the machine. I returned October’s. Do not write that accepting money meant agreeing to lose our house.” An’s draft says, “The families reconciled that year.”'),('Cách sửa nào phù hợp với thư?','Which revision matches the letter?'),[('Giữ nguyên câu hòa giải','Keep the reconciliation claim'),('Bỏ kết luận hòa giải, ghi rõ từng khoản nhận và trả','Remove the reconciliation claim; distinguish acceptance and return'),('Xóa toàn bộ lời của Lan','Remove all of Lan’s words')],1,('An sửa bản nháp. Lan nhắn một câu về chiếc máy may: “Nó vẫn chạy. Không phải tất cả những gì tới từ thời đó đều phải vứt đi.”','An revises the draft. Lan sends a line about the sewing machine: “It still runs. Not everything from that time has to be thrown away.”'))]},
{'id':'names_on_wall','title':b('Ngoại truyện · Tên trên bức tường','Side story · Names on the wall'),'unlock':3,'steps':[
step(('Danh sách đóng góp','The contributors'),('Danh sách xây tường ghi: hộ dân góp 8 triệu, trường góp 4 triệu, khoản chuyển từ hồ sơ Mai 12 triệu. Bảng tri ân chỉ viết “24 triệu do các hộ dân tự nguyện đóng góp”.','The wall ledger lists 8 million from residents, 4 million from the school, and 12 million transferred from Mai’s file. The plaque says “24 million voluntarily contributed by residents.”'),('Khoản nào không thể gọi là đóng góp tự nguyện của hộ dân?','Which cannot be called a voluntary household contribution?'),[('Khoản 12 triệu chuyển từ hồ sơ Mai','The 12 million diverted from Mai’s file'),('Khoản 8 triệu hộ dân góp','The residents’ 8 million'),('Không có khoản nào','None')],0,('Một bảng tên có thể kể sai ngay cả khi tổng tiền cộng đúng.','A plaque can tell a false story even when its arithmetic is correct.')),
step(('Hai tấm biển','Two plaques'),('Biên bản ngày 3/10 duyệt tấm biển thứ nhất, có dòng ghi nguồn tiền chuyển. Hóa đơn ngày 8/10 làm tấm thứ hai không có dòng ấy. Ảnh khánh thành ngày 12/10 cho thấy tấm thứ hai.','The 3 October minutes approve a plaque acknowledging the transferred funds. An 8 October invoice orders a second plaque without that line. The 12 October opening photograph shows the second plaque.'),('Chứng cứ nào xác nhận bản bỏ dòng nguồn tiền đã được lắp?','Which confirms the version omitting the funding source was installed?'),[('Biên bản ngày 3/10','3 October minutes'),('Ảnh ngày 12/10 đối chiếu hóa đơn 8/10','12 October photo compared with 8 October invoice'),('Chỉ tổng tiền trong sổ','Only the ledger total')],1,('Vinh xác nhận mình duyệt thay biển. Ông phải chịu trách nhiệm về cả con số lẫn cách công chúng được biết con số ấy.','Vinh confirms approving the replacement. He is responsible for both the money and the account presented to the public.')),
step(('Giữ lại dấu vết','Keeping a trace'),('Nhi muốn viết tên bà Mai lên tường. Lan muốn giữ tấm biển cũ như chứng cứ, nhưng không muốn địa chỉ nhà mình thành nơi người lạ tới chụp ảnh. Nhà trường đề nghị một bản chú thích tại phòng hồ sơ, dùng bản sao tấm biển và chỉ công khai thông tin đã được duyệt.','Nhi wants Mai’s name on the wall. Lan wants the old plaque preserved as evidence, but does not want strangers photographing her home. The school proposes an annotation in the archive using a copy of the plaque and only approved information.'),('Phương án nào giữ chứng cứ và tôn trọng yêu cầu của Lan?','Which preserves evidence and respects Lan’s request?'),[('Phá bỏ biển ngay','Destroy the plaque immediately'),('Đăng địa chỉ nhà Lan','Publish Lan’s home address'),('Giữ bản gốc, chú thích bản sao theo nội dung được duyệt','Preserve the original; annotate an approved copy')],2,('Nhi viết tên bà lên trang vở. Bức tường vẫn ở đó. Lần này, người đứng trước nó có thể đọc cả điều đã từng bị bỏ đi.','Nhi writes her grandmother’s name in her notebook. The wall remains. This time, a visitor can also read what had been left out.'))]}]
(ROOT/'data/side_stories.json').write_text(json.dumps(stories,ensure_ascii=False,indent=2),encoding='utf8')
